package main

import (
	"encoding/csv"
	"os"
	"path/filepath"
	"testing"
)

// Both databases are generated by the existing guarded test helper. Restoring
// the real writer's output verifies the new FK order and JSON/quantity fields.
func TestCraftWorkflowSnapshotRoundTripMySQL(t *testing.T) {
	source, _ := maintenanceFaultDB(t)
	target, _ := maintenanceFaultDB(t)
	dir := t.TempDir()
	t.Setenv("BACKUP_DIR", dir)
	for _, query := range []string{
		`INSERT INTO companies(id,name,ticket_mode) VALUES('restore-company','合成归档公司','split')`,
		`INSERT INTO projects(id,number,company_id,name,address,created_by,ticket_mode_snapshot) VALUES('restore-project','RST-P','restore-company','合成工地','合成地址','test','split')`,
		`INSERT INTO crafts(id,company_id,category,name,mode,price_cents,wage_cents,subitems) VALUES('restore-public','','开工','合成工艺','个',0,3000,'[{"id":"part-a","name":"小项甲"}]')`,
		`INSERT INTO crafts(id,company_id,category,name,mode,price_cents,wage_cents,source_id,ticket_slot) VALUES('restore-fixed','restore-company','开工','合成工艺','个',10000,0,'restore-public',1)`,
		`INSERT INTO orders(id,number,company_id,project_id,address,work_date,note,created_by,total_cents,wage_cents,delivery_wage_cents,ticket_managed) VALUES('restore-order','RST-O','restore-company','restore-project','合成地址','2026-10-01','','test',20200,6030,30,1)`,
		`INSERT INTO order_lines(id,order_id,craft_id,category,name,mode,segments,qty_micro,price_cents,wage_cents,total_cents,labor_cents,temporary,subitem_id,sort_order) VALUES('restore-line','restore-order','restore-fixed','开工','合成工艺','个','[{"mode":"个","count":2}]',2000000,10000,3000,20000,6000,0,'part-a',1)`,
		`INSERT INTO order_sales(id,order_id,product_id,warehouse_id,qty_micro,sale_qty_micro,price_cents,total_cents,product_name,unit,price_unit,input_unit,input_qty,sort_order) VALUES('restore-sale','restore-order','synthetic-product','synthetic-warehouse',1000000,1000000,200,200,'合成销售材料','桶','桶','base','1',1)`,
		`INSERT INTO project_craft_slots(project_id,craft_id,slot) VALUES('restore-project','restore-fixed',1)`,
		`INSERT INTO project_tickets(id,project_id,company_id,company_name,project_name,address,number,kind,slot,status,total_cents,version,created_at,updated_at) VALUES('restore-ticket','restore-project','restore-company','合成归档公司','合成工地','合成地址','RST-T','normal',1,'部分收款',20200,2,'2026-10-01','2026-10-01')`,
		`INSERT INTO project_ticket_items(item_id,ticket_id,order_id,item_kind) VALUES('restore-line','restore-ticket','restore-order','line'),('restore-sale','restore-ticket','restore-order','sale')`,
		`INSERT INTO project_ticket_versions(ticket_id,version,event,snapshot,created_by) VALUES('restore-ticket',1,'交票','{"total_cents":20200,"number":"RST-T"}','test')`,
		`INSERT INTO project_ticket_receipts(id,ticket_id,amount_cents,received_at,created_by) VALUES('restore-receipt','restore-ticket',10000,'2026-10-01','test')`,
	} {
		maintenanceFaultExec(t, source.db, query)
	}
	file, err := source.backup()
	if err != nil {
		t.Fatal(err)
	}
	if err = target.restore(filepath.Join(dir, file)); err != nil {
		t.Fatal("workflow snapshot restore", err)
	}
	for table, want := range map[string]int{"order_sales": 1, "project_craft_slots": 1, "project_tickets": 1, "project_ticket_items": 2, "project_ticket_versions": 1, "project_ticket_receipts": 1} {
		maintenanceFaultCount(t, target.db, "SELECT COUNT(*) FROM "+table, want)
	}
	var sourceID, subitem, ticketMode, snapshot string
	var saleQuantity, wage, received int64
	if err = target.db.QueryRow("SELECT source_id FROM crafts WHERE id='restore-fixed'").Scan(&sourceID); err != nil || sourceID != "restore-public" {
		t.Fatal("source association restore", sourceID, err)
	}
	if err = target.db.QueryRow("SELECT subitem_id FROM order_lines WHERE id='restore-line'").Scan(&subitem); err != nil || subitem != "part-a" {
		t.Fatal("subitem identity restore", subitem, err)
	}
	if err = target.db.QueryRow("SELECT ticket_mode_snapshot FROM projects WHERE id='restore-project'").Scan(&ticketMode); err != nil || ticketMode != "split" {
		t.Fatal("ticket grouping restore", ticketMode, err)
	}
	if err = target.db.QueryRow("SELECT sale_qty_micro FROM order_sales WHERE id='restore-sale'").Scan(&saleQuantity); err != nil || saleQuantity != 1000000 {
		t.Fatal("sale quantity restore", saleQuantity, err)
	}
	if err = target.db.QueryRow("SELECT delivery_wage_cents FROM orders WHERE id='restore-order'").Scan(&wage); err != nil || wage != 30 {
		t.Fatal("delivery wage restore", wage, err)
	}
	if err = target.db.QueryRow("SELECT JSON_UNQUOTE(JSON_EXTRACT(snapshot,'$.number')) FROM project_ticket_versions WHERE ticket_id='restore-ticket'").Scan(&snapshot); err != nil || snapshot != "RST-T" {
		t.Fatal("ticket version restore", snapshot, err)
	}
	if err = target.db.QueryRow("SELECT SUM(amount_cents) FROM project_ticket_receipts WHERE ticket_id='restore-ticket'").Scan(&received); err != nil || received != 10000 {
		t.Fatal("receipt restore", received, err)
	}
	// Sale, ticket and receipt CSVs include exactly one current amount and put
	// their total under the monetary header, so Excel does not treat it as an ID.
	archiveDir := t.TempDir()
	tx, err := target.db.Begin()
	if err != nil {
		t.Fatal(err)
	}
	defer tx.Rollback()
	files := []ArchiveFile{}
	if err = appendWorkflowArchives(tx, "2026-10-01", "2026-11-01", "restore-company", "run", archiveDir, &files); err != nil {
		t.Fatal(err)
	}
	if len(files) != 3 {
		t.Fatal("expected sales/tickets/receipts archive", files)
	}
	for _, item := range files {
		f, e := os.Open(filepath.Join(archiveDir, filepath.Base(item.File)))
		if e != nil {
			t.Fatal(e)
		}
		r := csv.NewReader(f)
		records, e := r.ReadAll()
		f.Close()
		if e != nil {
			t.Fatal("inconsistent archive CSV width", e)
		}
		if len(records) != 3 {
			t.Fatalf("unexpected duplicate or missing archive rows %s: %d", item.Kind, len(records))
		}
		column := 8
		want := "2.00"
		if item.Kind == "票据应收" {
			column = 6
			want = "202.00"
		}
		if item.Kind == "收款流水" {
			want = "100.00"
		}
		if records[2][column] != want {
			t.Fatalf("archive monetary total is in wrong column: %s %+v", item.Kind, records[2])
		}
	}
}
